const input = $json.body ?? $json;
const required = ['form_type','market','submitted_at'];
const missing = required.filter(k => !String(input[k] ?? '').trim());
const urgencyMap = {'ASAP':20,'Urgent':20,'Same day if possible':20,'Today':15,'Within 7 days':10,'Within 30 days':5};
const urgency = input.timing || input.urgency || '';
const consent = String(input.consent || '').toLowerCase() === 'yes';
let score = urgencyMap[urgency] || 0;
if (input.email || input.phone) score += 20;
if (String(input.scope || input.problem || '').length >= 20) score += 15;
if (consent) score += 20;
if (input.market) score += 15;
const normalized = {
  lead_id: `lead_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
  submitted_at: input.submitted_at || new Date().toISOString(),
  form_type: input.form_type || 'unknown',
  market: input.market || '',
  service_type: input.service_type || input.equipment_type || '',
  customer_name: input.contact_name || input.name || '',
  business_name: input.business_name || '',
  email: input.email || '',
  phone: input.phone || '',
  preferred_contact: input.preferred_contact || '',
  scope: input.scope || input.problem || input.notes || '',
  urgency,
  source_page: input.page || '',
  consent,
  lead_score: score,
  status: missing.length || !consent ? 'exception' : 'received',
  exception_reason: missing.length ? `missing:${missing.join(',')}` : (!consent ? 'missing_consent' : '')
};
return [{json:normalized}];
